ART_LIBRARY=json.loads((Path(__file__).parent/'art_library.json').read_text())
NOTES={
 'philosophers':('Два человека на одной дороге','На картине Нестерова «Философы» изображены Павел Флоренский и Сергей Булгаков. В философской мастерской полотно сопровождает вопрос о победе добра; это наше сопоставление, а не приписанный художнику тезис.','Как фигуры остаются различными и одновременно воспринимаются вместе? Опирайтесь на положение, одежду, жесты и пейзаж.'),
 'ninth-wave':('Свет и ещё не миновавшая опасность','«Девятый вал» Айвазовского соединяет рассветное сияние и людей среди огромных волн. Рядом со статьёй о надежде важно заметить: спасение ещё не показано как завершённый факт.','Переведите взгляд с неба на людей. Как меняется ваше прочтение надежды?'),
 'levitan':('Пейзаж и пространство памяти','Пейзаж Левитана можно сопоставить с литературными образами дома, дороги и вечернего покоя. Это самостоятельная картина, не иллюстрация к одному из рассказов.','Как соотносятся ближний берег, вода и удалённый монастырь? Найдите у выбранного писателя сходный способ разделить близкое и далёкое.'),
 'onegin':('Художник читает роман','Клодт выбирает из протяжённого повествования один видимый момент жизни Татьяны. Изображение позволяет обсудить, чего живопись не может сообщить без читательского знания.','Какие наблюдения подтверждает картина сама, а какие вы добавляете из романа?'),
 'pechorin':('Портрет как интерпретация','Врубель даёт зрительный образ Печорина. Не стоит выводить весь характер из выражения лица: текст романа предоставляет несколько точек зрения и временных планов.','Какую деталь рисунка можно сопоставить с текстовым портретом? Где начинается самостоятельное прочтение художника?'),
 'igor':('После сражения','Васнецов показывает последствие битвы. Эпический масштаб и неподвижность тел создают сочетание величия и утраты. Картина написана много веков спустя после похода.','Как выбор момента после боя меняет восприятие военного сюжета? Сопоставьте с плачем Ярославны.'),
 'alenushka':('Одиночество, которое стало видимым','Поза девушки, неподвижная вода и окружающий пейзаж позволяют говорить о замкнутости и печали. Название связывает картину со сказочным кругом, но не превращает каждую её деталь в событие народной сказки.','Какие три видимые детали создают впечатление одиночества? Затем сравните с тем, как печаль показана в прочитанном тексте.'),
 'bilibin':('Сказка и книжная страница','Это иллюстрация к «Василисе Прекрасной»: героиня несёт череп на шесте. Орнаментальная рама, линия и условное пространство принадлежат книжной графике. Для младших детей выбирайте изображение вместе со взрослым, после знакомства с сюжетом.','Как орнамент и повтор вертикалей продолжают сказочный мир за пределами самой сцены? Не называйте эту работу иллюстрацией к другой сказке.'),
 'troika':('Труд, превышающий детские силы','Перов делает детский труд главным предметом внимания. Направление движения, наклон фигур и тяжесть бочки позволяют обсуждать не только усилие, но и устройство отношений взрослых и детей.','Как художник показывает тяжесть без письменного объяснения? Сравните с деталью труда у Некрасова.'),
 'rooks':('Ранняя весна без праздничной условности','Саврасов выбирает переходное состояние: снег ещё лежит, но птицы и вода меняют вид привычного места. Стихотворение и картина способны по-разному организовать ощущение наступающего времени.','Назовите признаки зимы и весны. Какие из них легко передать звуком, а какие требуют зрительного образа?'),
 'bartholomew':('Житийный сюжет в живописи XIX века','Нестеров обращается к преданию о детстве Сергия Радонежского. Это религиозная живопись позднего времени, не древняя икона и не документальная запись встречи. Пейзаж становится частью рассказа о призвании.','Как жесты двух фигур и расстояние между ними создают отношение? Сравните картину с прочитанным фрагментом жития.'),
 'prodigal':('Возвращение и принятие','Рембрандт обращается к притче о блудном сыне. Живописная интерпретация делает видимыми жест встречи и присутствие свидетелей. Евангельский текст и картина имеют самостоятельное устройство.','Куда направлен свет и как расположены руки отца? Сопоставьте с тем, что у Пушкина в «Станционном смотрителе» не повторяет притчу.'),
 'trinity':('Священный образ и язык единения','Икона Троицы имеет самостоятельное богословское и молитвенное содержание. Рассмотрение композиции — только первый шаг знакомства с ней. Нельзя свести её к общей иллюстрации дружбы или заменить ею объяснение любой тройки литературных персонажей.','Проследите направления взглядов, наклоны фигур и интервалы между ними. Чем этот способ организации целого отличается от последовательного рассказа о событии?'),
 'vladimir':('Материнская близость и священный образ','Икона Богоматери не является бытовым портретом матери с ребёнком. Сопоставляя её с поэзией материнства, отмечаем близость жеста и различие назначения произведений. Музейные сведения указывают атрибуцию и происхождение репродукции, а не текущее место показа.','Как соприкосновение лиц и направление взгляда создают одновременно близость и обращённость за пределы изображения?'),
 'nativity':('Несколько событий в одном пространстве','На иконе Рождества разные эпизоды представлены вместе. Их пространственное соседство не следует читать как фотографию единственного мгновения. Авторство и дата приводятся с оговорками музейного каталога.','Выделите группы фигур. Чем одновременное присутствие эпизодов отличается от последовательности рассказа у писателя?'),
 'jairus':('Жест помощи и евангельское событие','Фреска относится к евангельскому рассказу о дочери Иаира. При сопоставлении с литературной темой надежды сначала различите конкретные библейские сюжеты: дочь Иаира и Лазарь — не одно лицо и не один эпизод.','Как жест Христа организует внимание остальных фигур? Что в литературном тексте могло бы выполнять подобную направляющую функцию?'),
}

NOTES.update({
 'lermontov-kobi':('Кавказский пейзаж','Пейзаж Лермонтова сопровождает общий кавказский маршрут. Он создан независимо от произведений Толстого; изображённый вид находится близ Коби.',''),
 'gagarin-hadji-murat':('Лицо исторического человека','Портрет Хаджи-Мурата, выполненный его современником Григорием Гагариным. Он сопровождает чтение повести, сохраняя различие между реальным прообразом и литературным героем.',''),
 'truth-pilate':('Истина перед лицом власти','Ге обращается к евангельской встрече Христа и Пилата. Контраст света и тени сопровождает размышление о власти и ответственности. Это религиозная живопись XIX века, а не богослужебная икона.',''),
 'mental-count':('Каждый думает по-своему','Богданов-Бельский показывает школьников за общим делом. Разные позы и выражения лиц сохраняют отдельность каждого ребёнка.',''),
 'moonlit-dnieper':('Свет над тёмной водой','Лунный свет у Куинджи делает привычный речной пейзаж почти таинственным. Картина сопровождает темы тишины, неизвестности и надежды.',''),
})

def publish_art(page):
    uses={key:[] for key in ART_LIBRARY}
    from philosophy_essays import ESSAYS
    for article in ESSAYS:
        uses[article['art']].append((f'/filosofiya/{article["slug"]}/',article['title']))
    for n,g in load_grades().items():
        for u in g['units']:
            if u['art']:
                uses[u['art']].append((f'/shkola/{n}/{u["id"]}/',f'{n} класс · {u["title"]}'))
    from extra_reading import ESSAYS as textbook_essays, CATALOGUE_ESSAYS, INDEPENDENT_ESSAYS
    for article in textbook_essays + CATALOGUE_ESSAYS + INDEPENDENT_ESSAYS:
        uses[article['art']].append((f'/chtenie/razbory/{article["slug"]}/', article['title']))
    groups=[]
    for group,label in [('secular','Живопись и книжная графика'),('church','Иконы и фреска')]:
        cards=[]
        for key,a in ART_LIBRARY.items():
            if a['group']!=group: continue
            title,comment,question=NOTES[key]
            relations=''.join(f'<li><a href="{url}">{e(text)}</a></li>' for url,text in uses[key])
            related=f'<details class="art-related"><summary>Где читать рядом с этой работой · {len(uses[key])}</summary><ul>{relations}</ul></details>' if relations else '<p><a href="/chtenie-i-tradiciya/">О границах литературного и духовного сопоставления</a></p>'
            cards.append(f'<article class="gallery-card" id="{key}"><div class="gallery-image">{figure(a)}</div><div class="gallery-comment"><p class="eyebrow">Рядом с прочитанным</p><h3>{e(title)}</h3><p>{e(comment)}</p>{related}<p><a href="#gallery-index">К перечню работ</a></p></div></article>')
        groups.append(f'<section class="gallery-group" id="{group}"><h2>{label}</h2>{"".join(cards)}</section>')
    nav=''.join(f'<li><a href="#{key}">{e(a["artist"])}. {e(a["title"])}</a></li>' for key,a in ART_LIBRARY.items())
    body=f'''<div class="wrap"><header class="page-title"><p class="eyebrow">Живопись · книжная графика · церковное искусство</p><h1>Увидеть рядом<br>с прочитанным</h1><p class="lead">{len(ART_LIBRARY)} произведений художников и иконописцев. Репродукции рядом с литературными и философскими статьями.</p></header><div class="catalogue-intro"><p>Иногда картина помогает почувствовать то, что трудно сразу объяснить словами: одиночество, покой, тревогу, радость встречи. Здесь собраны иллюстрации к чтению. Подпись поясняет, связана ли работа с самой книгой или выбрана нами по настроению и теме.</p><p><a href="/muzyka/">Перейти к музыкальным записям</a> · <a href="/shkola/">Выбрать класс и произведение</a></p></div><nav class="school-topics" id="gallery-index" aria-label="Произведения искусства"><h2>Перечень работ</h2><ul>{nav}</ul></nav>{''.join(groups)}<p class="fine">Репродукции взяты из источников, указывающих общественное достояние. Композиции сохранены; выполнены только соразмерное уменьшение и сжатие файлов. Сведения и источники указаны у каждой репродукции. Живопись, изображения и музыка для проекта не генерируются.</p></div>'''
    page('/iskusstvo/','Живопись и церковное искусство','Произведения художников, иконы и фреска рядом с литературой: источники, полные репродукции и подписи.',body,active='art')
